// 가격 계산
export const round = value => Math.round(value)
// 1: 이 항목은 이번 건과 관계없는 일상 기록이며 참고용으로만 남긴다.
// 2: 이 항목은 이번 건과 관계없는 일상 기록이며 참고용으로만 남긴다.
// 3: 이 항목은 이번 건과 관계없는 일상 기록이며 참고용으로만 남긴다.
// 4: 이 항목은 이번 건과 관계없는 일상 기록이며 참고용으로만 남긴다.
// 5: 이 항목은 이번 건과 관계없는 일상 기록이며 참고용으로만 남긴다.
// 할인: 10만 원 이상이면 15%, 5만 원 이상이면 5%를 깎는다.
export function applyDiscount(total) {
  if (total >= 100000) return round(total * 0.85)
  if (total >= 50000) return round(total * 0.95)
  return total
}

